<script>
  export let data;
  const filters = [['new', 'New'], ['limited', 'Limited editions'], ['open', 'Open editions'], ['kenya', 'From Kenya']];
  const money = (amount, currency) => new Intl.NumberFormat('en-KE', { style: 'currency', currency: currency || 'KES', maximumFractionDigits: 0 }).format(Number(amount || 0));
  const availability = (item) => item.edition_size == null ? 'Open Edition' : `${Math.max(0, item.edition_size - (item.acquired_count ?? 0))} of ${item.edition_size} available`;
  const copyLabel = (item) => item.edition_size ? `Copy ${String(item.serial ?? 1).padStart(2, '0')}/${item.edition_size}` : 'Open Edition';
  const eventLabel = (kind) => ({ acquired: 'Primary acquisition completed', transferred: 'Ownership transferred', created: 'Copy issued', verified: 'Authenticity verified', royalty_paid: 'Artist royalty paid' }[kind] || String(kind).replaceAll('_', ' '));
</script>

<svelte:head><title>Noizes Exchange — Discover cultural objects</title></svelte:head>

<div class="exchange-page">
  <header class="exchange-heading"><div><p class="eyebrow">Noizes Exchange</p><h1>Exchange</h1><p class="lede">Collect music as complete cultural objects.</p></div><form class="search" action="/exchange"><label class="sr-only" for="exchange-search">Search works, artists, editions and copies</label><span aria-hidden="true">⌕</span><input id="exchange-search" name="q" value={data.query} placeholder="Search releases, artists and editions" /><button type="submit">Search</button></form></header>
  <nav class="mode-nav" aria-label="Exchange modes"><a class:active={true} href="/exchange">Discover</a><a href="/exchange/collector-market">Collector Market</a><a href="/exchange/provenance">Provenance Records</a></nav>
  {#if data.loadError}<div class="notice" role="alert">{data.loadError.message}</div>{/if}
  <div class="filter-row" aria-label="Discover filters">{#each filters as [value, label]}<a class:chosen={data.selectedFilter === value} href={`/exchange?filter=${value}${data.query ? `&q=${encodeURIComponent(data.query)}` : ''}`}>{label}</a>{/each}</div>

  {#if data.featured}<section class="feature" aria-labelledby="featured-title"><div class="feature-copy"><p class="eyebrow">Featured cultural object</p><p class="artist">{data.featured.artist_name}</p><h2 id="featured-title">{data.featured.title}</h2><p class="description">{data.featured.description || 'A complete, portable music object with its own edition identity and cultural record.'}</p><div class="metadata"><span>◈ {data.featured.release_type || 'Music object'}</span><span>{data.featured.edition_name || data.featured.edition_type}</span><strong>{availability(data.featured)}</strong></div><div class="feature-actions"><a class="primary" href={data.featured.artist_slug && data.featured.slug ? `/drop/${data.featured.artist_slug}/${data.featured.slug}` : '#catalogue'}>Explore object <span>→</span></a><a class="secondary" href={data.featured.artist_slug && data.featured.slug ? `/drop/${data.featured.artist_slug}/${data.featured.slug}` : '#catalogue'}>Enter preview</a></div></div><div class="feature-image">{#if data.featured.cover_url}<img src={data.featured.cover_url} alt={`${data.featured.title} cover artwork`} />{:else}<div class="art-placeholder">NOIZES</div>{/if}</div></section>{/if}

  <section class="section" aria-labelledby="market-title"><div class="section-title"><div><p class="eyebrow">Authenticated copies</p><h2 id="market-title">Collector Market</h2><p>Authenticated editions offered by their current custodians.</p></div><a href="/exchange/collector-market">Explore Collector Market →</a></div>{#if data.market.length}<div class="market-grid">{#each data.market.slice(0, 4) as item}<article class="market-card">{#if item.cover_url}<img src={item.cover_url} alt="" />{:else}<div class="card-art">NZ</div>{/if}<div class="market-copy"><p class="artist">{item.artist_name}</p><h3>{item.title}</h3><p class="copy">▣ {copyLabel(item)}</p><p class="record">◈ Registry verified · Provenance recorded</p><div><strong>{money(item.ask, item.currency)}</strong><span>Offers open</span></div><a href={item.href}>View copy <b>→</b></a></div></article>{/each}</div>{:else}<p class="empty">No custodians are accepting offers right now. Authenticated copies remain visible through their object records.</p>{/if}</section>

  {#if data.activity.length}<section class="activity" aria-labelledby="activity-title"><div class="section-title"><div><p class="eyebrow">The living record</p><h2 id="activity-title">Recent provenance</h2></div><a href="/exchange/provenance">View records →</a></div><div class="activity-list">{#each data.activity as event}<a href={event.acquisition_id ? `/exchange/copy/${event.acquisition_id}` : '/exchange/provenance'}><span class="activity-mark">↗</span>{#if event.cover_url}<img src={event.cover_url} alt="" />{/if}<span><b>{event.title}</b><small>{eventLabel(event.kind)} · {new Date(event.occurred_at).toLocaleDateString('en-KE', { month: 'short', day: 'numeric' })}</small></span></a>{/each}</div></section>{/if}

  <section id="catalogue" class="section catalogue" aria-labelledby="catalogue-title"><div class="section-title"><div><p class="eyebrow">Complete catalogue</p><h2 id="catalogue-title">New cultural objects</h2><p>Fresh releases from artists shaping tomorrow.</p></div></div><div class="catalogue-grid">{#each data.catalogue as item}<article class="object-card">{#if item.cover_url}<img src={item.cover_url} alt={`${item.title} artwork`} />{:else}<div class="card-art">{item.artist_name?.slice(0, 2)}</div>{/if}<div class="object-info"><p class="artist">{item.artist_name}</p><h3>{item.title}</h3><p>{item.edition_name || item.edition_type} · {availability(item)}</p><div><strong>{money(item.price, item.currency)}</strong><a href={item.artist_slug && item.slug ? `/drop/${item.artist_slug}/${item.slug}` : '#'}>Explore</a></div></div></article>{/each}</div>{#if !data.catalogue.length}<p class="empty">No cultural objects match these filters.</p>{/if}</section>
</div>

<style>
 .exchange-page{max-width:1560px;margin:0 auto;padding:36px clamp(18px,4vw,56px) 80px;color:#f8f7fb}.exchange-heading{display:flex;justify-content:space-between;gap:2rem;align-items:end;margin-bottom:26px}.eyebrow{color:#b795ff;text-transform:uppercase;letter-spacing:.15em;font-size:.68rem;font-weight:800;margin:0 0 8px}.exchange-heading h1,.feature h2,.section h2{margin:0;color:white;letter-spacing:-.06em;font-weight:900}.exchange-heading h1{font-size:clamp(3.8rem,7vw,6.5rem);line-height:.82}.lede{font-size:1.2rem;color:#c7c2d6;margin:13px 0 0}.search{display:flex;align-items:center;width:min(430px,100%);border:1px solid #2b2b3c;border-radius:999px;background:#12121a;padding:4px 5px 4px 14px}.search span{font-size:1.5rem;color:#b8b3cc}.search input{border:0;outline:0;background:transparent;color:white;min-width:0;flex:1;padding:11px;font:inherit}.search button{border:0;border-radius:999px;background:#7043f7;color:white;padding:10px 16px;font-weight:800}.mode-nav{display:flex;border:1px solid #302e40;border-radius:999px;overflow:hidden;width:fit-content;max-width:100%;margin-bottom:18px;background:#0d0d13}.mode-nav a{padding:11px 26px;color:#bcb7ca;text-decoration:none;font-weight:700;white-space:nowrap}.mode-nav a.active,.mode-nav a:hover{background:linear-gradient(110deg,#7043f7,#9a4cf5);color:#fff}.filter-row{display:flex;gap:8px;overflow-x:auto;padding-bottom:10px}.filter-row a{white-space:nowrap;text-decoration:none;color:#d5d0e2;border:1px solid #373345;border-radius:999px;padding:8px 15px;font-size:.85rem}.filter-row a.chosen{background:#fff;color:#111;border-color:#fff}.feature{display:grid;grid-template-columns:1fr minmax(380px,1.18fr);min-height:470px;margin:26px 0 60px;background:#0c0c12;border:1px solid #272536;overflow:hidden}.feature-copy{padding:clamp(28px,5vw,70px);align-self:center;position:relative;z-index:2}.feature h2{font-size:clamp(3rem,6vw,6.8rem);line-height:.86}.artist{color:#a57aff!important;font-size:.72rem!important;text-transform:upperca