color:#b7b1c7;font-size:.72rem}.market-copy>div,.object-info>div{display:flex;align-items:center;justify-content:space-between;gap:8px}.market-copy strong,.object-info strong{font-size:1.1rem}.market-copy span{color:#ffc45d;border:1px solid #a8792c;border-radius:999px;padding:3px 8px;font-size:.69rem}.market-copy>a{display:block;color:white;text-align:center;text-decoration:none;background:#6c3cf5;border-radius:8px;padding:9px;margin-top:13px;font-weight:800}.market-copy>a b{margin-left:10px;font-size:1.2rem}.activity{background:#111117;border:1px solid #292637;border-radius:13px;padding:18px}.activity .section-title{margin-bottom:12px}.activity-list{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.activity-list a{min-width:0;display:flex;align-items:center;gap:9px;text-decoration:none;color:#e7e1f1;padding:7px;border-left:1px solid #b98545}.activity-list img{width:42px;height:42px;object-fit:cover;border-radius:4px}.activity-mark{color:#ffc258;font-size:1.2rem}.activity-list b,.activity-list small{display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.activity-list small{color:#b7b1c7;font-size:.75rem;margin-top:3px}.object-card>img,.object-card>.card-art{display:block;width:100%;aspect-ratio:1;object-fit:cover}.object-info{padding:13px}.object-info>p:not(.artist){font-size:.78rem;color:#bcb6c8;margin:0 0 13px}.object-info a{color:white;background:#683af2;border-radius:999px;text-decoration:none;padding:6px 11px;font-size:.75rem;font-weight:800}.empty,.notice{padding:22px;border:1px solid #393449;border-radius:10px;color:#c6bfd4;background:#121118}.notice{border-color:#a17b37;color:#ffe0a0}@media(max-width:900px){.market-grid,.catalogue-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.activity-list{grid-template-columns:1fr}.feature{grid-template-columns:1fr;min-height:0}.feature-image{height:360px;order:-1}.feature-image:after{background:linear-gradient(0deg,#0c0c12,transparent 60%)}.exchange-heading{align-items:start;flex-direction:column}.search{width:100%}}@media(max-width:560px){.exchange-page{padding:24px 15px 60px}.exchange-heading h1{font-size:4rem}.mode-nav{width:100%;overflow-x:auto}.mode-nav a{padding:10px 16px;font-size:.84rem}.feature-copy{padding:28px 20px}.feature h2{font-size:3.6rem}.feature-image{height:270px}.market-grid,.catalogue-grid{gap:8px}.market-card{padding:6px}.market-copy h3,.object-info h3{font-size:1rem}.market-copy .record{display:none}.section-title{align-items:start;flex-direction:column}.section-title>a{font-size:.82rem}.activity{padding:13px}}
</style>
